-- قاعدة بيانات «دفتري» بمخطط الإصدار 1 (أنشأها الكود القديم نفسه) لاختبار الترحيل إلى الإصدار 2.
-- تحتوي: حساباً مؤرشفاً برصيد، أشخاصاً مخفيين (مسدد / عليه دين)، عنواناً، ديناً بلا حساب، ودفعة «في الدفتر فقط».
BEGIN TRANSACTION;
CREATE TABLE "accounts" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL UNIQUE, "type" TEXT NOT NULL, "currency_id" INTEGER NOT NULL REFERENCES currencies (id), "opening_balance" INTEGER NOT NULL DEFAULT 0, "balance" INTEGER NOT NULL DEFAULT 0, "is_default" INTEGER NOT NULL DEFAULT 0 CHECK ("is_default" IN (0, 1)), "is_archived" INTEGER NOT NULL DEFAULT 0 CHECK ("is_archived" IN (0, 1)), "archived_at" INTEGER NULL, "icon" TEXT NULL, "color" INTEGER NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "backup_logs" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" TEXT NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "size_kb" INTEGER NOT NULL DEFAULT 0, "status" TEXT NOT NULL);
CREATE TABLE "budgets" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "category_id" INTEGER NOT NULL REFERENCES categories (id) ON DELETE CASCADE, "limit_amount" INTEGER NOT NULL CHECK("limit_amount" > 0), "period" TEXT NOT NULL, "alert_percent" INTEGER NOT NULL DEFAULT 75, UNIQUE ("category_id", "period"));
CREATE TABLE "categories" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "kind" TEXT NOT NULL, "parent_id" INTEGER NULL REFERENCES categories (id), "icon" TEXT NOT NULL, "color" INTEGER NOT NULL, "is_default" INTEGER NOT NULL DEFAULT 0 CHECK ("is_default" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "contacts" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "phone" TEXT NULL, "address" TEXT NULL, "note" TEXT NULL, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "currencies" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "symbol" TEXT NOT NULL, "is_base" INTEGER NOT NULL DEFAULT 1 CHECK ("is_base" IN (0, 1)), "decimals" INTEGER NOT NULL DEFAULT 2);
CREATE TABLE "debt_payments" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "debt_id" INTEGER NOT NULL REFERENCES debts (id) ON DELETE CASCADE, "amount" INTEGER NOT NULL CHECK("amount" > 0), "paid_at" INTEGER NOT NULL, "account_id" INTEGER NULL REFERENCES accounts (id), "note" TEXT NULL);
CREATE TABLE "debts" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "contact_id" INTEGER NOT NULL REFERENCES contacts (id), "direction" TEXT NOT NULL, "amount" INTEGER NOT NULL CHECK("amount" > 0), "paid_amount" INTEGER NOT NULL DEFAULT 0, "currency_id" INTEGER NOT NULL REFERENCES currencies (id), "account_id" INTEGER NULL REFERENCES accounts (id), "start_date" INTEGER NOT NULL, "due_date" INTEGER NULL, "status" TEXT NOT NULL, "note" TEXT NULL, "remind" INTEGER NOT NULL DEFAULT 0 CHECK ("remind" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "settings" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "transactions" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "type" TEXT NOT NULL, "amount" INTEGER NOT NULL CHECK("amount" IS NOT 0 AND ("amount" > 0 OR "type" = 'adjustment')), "currency_id" INTEGER NOT NULL REFERENCES currencies (id), "account_id" INTEGER NOT NULL REFERENCES accounts (id), "to_account_id" INTEGER NULL REFERENCES accounts (id), "category_id" INTEGER NULL REFERENCES categories (id), "debt_id" INTEGER NULL REFERENCES debts (id), "debt_payment_id" INTEGER NULL REFERENCES debt_payments (id), "date" INTEGER NOT NULL, "note" TEXT NULL, "receipt_path" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE UNIQUE INDEX idx_accounts_single_default ON accounts (is_default) WHERE is_default = 1;
CREATE INDEX idx_categories_kind ON categories (kind, sort_order);
CREATE INDEX idx_tx_date ON transactions (date);
CREATE INDEX idx_tx_account_date ON transactions (account_id, date);
CREATE INDEX idx_tx_to_account ON transactions (to_account_id);
CREATE INDEX idx_tx_category_date ON transactions (category_id, date);
CREATE INDEX idx_tx_debt ON transactions (debt_id);
CREATE INDEX idx_tx_debt_payment ON transactions (debt_payment_id);
CREATE INDEX idx_debts_contact ON debts (contact_id);
CREATE INDEX idx_debts_status_due ON debts (status, due_date);
CREATE INDEX idx_payments_debt ON debt_payments (debt_id, paid_at);
CREATE TRIGGER trg_accounts_no_delete
      BEFORE DELETE ON accounts
      BEGIN
        SELECT RAISE(ABORT, 'accounts_cannot_be_deleted');
      END;
DELETE FROM "sqlite_sequence";
COMMIT;
PRAGMA user_version = 1;
